import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.9ngYh_O2.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"自主无人机开发学习手册","text":"一个新手把 EGO-Planner 真正跑起来的全过程","tagline":"每条命令都实测过，每张截图都是真机画面，每个结论都标了证据来源","actions":[{"theme":"brand","text":"从第一步开始","link":"/getting-started/environment"},{"theme":"alt","text":"直接看仿真怎么跑","link":"/ego-planner/simulation"}]},"features":[{"title":"照着敲就能复现","details":"命令一个字都没简化，每个参数都解释了\\"去掉会怎样\\"，配真实终端和 RViz 截图。"},{"title":"证据分级，不吹不猜","details":"【源码确认】给出 文件:行号，【运行验证】给出真实输出，【推测】和【待验证】绝不伪装成结论。"},{"title":"只写真实踩过的坑","details":"排错页里没有一条是编造的\\"可能问题\\"，全部来自实际报错，并写清了为什么会发生。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788503940000}'),n={name:"index.md"};function o(l,t,i,s,c,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h2 id="这份文档是什么" tabindex="-1">这份文档是什么 <a class="header-anchor" href="#这份文档是什么" aria-label="Permalink to &quot;这份文档是什么&quot;">​</a></h2><p>一个<strong>完全的新手</strong>在自己的笔记本上，从零把 <a href="https://github.com/ZJU-FAST-Lab/ego-planner-swarm" target="_blank" rel="noreferrer">EGO-Planner</a>（浙江大学 FAST-Lab 的无人机局部轨迹规划器）的 ROS 2 版本跑起来的真实记录。</p><p>目标不是&quot;能跑就行&quot;，而是<strong>环境可复现 + 项目可运行 + 源码能理解 + 能自己改</strong>。所以每一步都会回答四个问题：现在在做什么、为什么需要它、怎么验证成功了、我应该记住什么。</p><h2 id="当前进度" tabindex="-1">当前进度 <a class="header-anchor" href="#当前进度" aria-label="Permalink to &quot;当前进度&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">单机仿真已经跑通并完成验收【运行验证】</p><ul><li>Docker 镜像 <code>local/ego-planner-humble:latest</code>（4.84 GB）构建成功</li><li><code>colcon build</code> <strong>20 个包全部成功</strong>，无失败</li><li>8 个节点全部起来，闭环数据流稳定：<code>pos_cmd</code> <strong>100.002 Hz</strong>，标准差 0.07 ms</li><li>RViz 硬件渲染正常（<code>OpenGl version: 4.6</code>），能看到无人机在柱子林里来回穿行</li><li>状态机走通 <code>INIT → WAIT_TARGET → GEN_NEW_TRAJ → EXEC_TRAJ ⇄ REPLAN_TRAJ</code>，单次优化 <strong>0.512 ms</strong></li></ul></div><p>四项验收全过。下一步是系统地读源码，以及往后接 VINS / PX4，路线见 <a href="/drone-learning-lab/getting-started/roadmap">学习路线</a>。</p><h2 id="怎么用这份文档" tabindex="-1">怎么用这份文档 <a class="header-anchor" href="#怎么用这份文档" aria-label="Permalink to &quot;怎么用这份文档&quot;">​</a></h2><p>四页按顺序看，每页都能独立验收：</p><table tabindex="0"><thead><tr><th>页面</th><th>你会得到</th><th>大概耗时</th></tr></thead><tbody><tr><td><a href="/drone-learning-lab/getting-started/environment">第一步：搭环境</a></td><td>一个不污染宿主机的 ROS 2 Humble 容器</td><td>首次 15~30 分钟</td></tr><tr><td><a href="/drone-learning-lab/ego-planner/build">第二步：编译工作空间</a></td><td>20 个包编译完成，<code>ros2 pkg list</code> 能认出来</td><td>首次 10~20 分钟</td></tr><tr><td><a href="/drone-learning-lab/ego-planner/simulation">第三步：跑通单机仿真</a></td><td>看得见的飞行画面 + 4 项验收</td><td>首次 20 分钟，之后 2 分钟</td></tr><tr><td><a href="/drone-learning-lab/ego-planner/source-reading">第四步：读懂源码</a></td><td>6390 行 C++ 的阅读路线、状态机全图、两个可回滚的小修改练习</td><td>读 1~2 小时</td></tr></tbody></table><p>卡住了就看排错页：<a href="/drone-learning-lab/debugging/docker-build">构建期问题</a>、<a href="/drone-learning-lab/debugging/ego-runtime">运行期问题</a>。</p><h2 id="证据标签怎么读" tabindex="-1">证据标签怎么读 <a class="header-anchor" href="#证据标签怎么读" aria-label="Permalink to &quot;证据标签怎么读&quot;">​</a></h2><p>文档里每个重要结论都带标签，<strong>请按标签决定信任程度</strong>：</p><table tabindex="0"><thead><tr><th>标签</th><th>含义</th><th>你可以怎么用</th></tr></thead><tbody><tr><td>【源码确认】</td><td>读了源码，给出 <code>文件:行号</code></td><td>可以直接引用，自己也能去核对</td></tr><tr><td>【运行验证】</td><td>在本机真实执行过，附真实输出</td><td>可以照着复现</td></tr><tr><td>【推测】</td><td>合理解释，但没有直接证据</td><td>当思路参考，不要当事实</td></tr><tr><td>【待验证】</td><td>还没做过</td><td>只是计划，不要当成能用的方案</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这份文档的局限</p><p>所有结论都来自<strong>一台机器</strong>：Ubuntu 24.04.3 + RTX 4060 + X11 桌面。换硬件、换发行版、用 Wayland，都可能不一样——尤其是显卡设备号和图形转发部分。<strong>遇到不一致时，相信你机器上的实际输出，不要相信这份文档。</strong></p></div><h2 id="关于第三方代码" tabindex="-1">关于第三方代码 <a class="header-anchor" href="#关于第三方代码" aria-label="Permalink to &quot;关于第三方代码&quot;">​</a></h2><p>EGO-Planner 由<strong>浙江大学 FAST-Lab</strong> 开发并以 <strong>GPL-3.0</strong> 授权，上游仓库是 <a href="https://github.com/ZJU-FAST-Lab/ego-planner-swarm" target="_blank" rel="noreferrer">ZJU-FAST-Lab/ego-planner-swarm</a>（本项目用 <code>ros2_version</code> 分支，<code>23a8d5a</code>）。</p><p>本项目<strong>只是学习复现</strong>：不把上游源码复制进本仓库，不修改第三方代码，不把上游 README 当成自己的内容。文档里所有对源码的引用都注明了 <code>文件:行号</code>，方便你回到原仓库核对。算法和实现的功劳属于原作者。</p>',17)])])}const p=e(n,[["render",o]]);export{b as __pageData,p as default};
